<?php
namespace Tests\Feature;
use App\Domain\Network\Billing\Models\{Entitlement,Subscription,UsageEvent};use App\Domain\Network\Billing\{EntitlementService,SubscriptionService,UsageService};use App\Domain\Network\Catalog\Models\{Module,Plan};use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\Roles\Roles;use App\Models\User;use Illuminate\Database\QueryException;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Carbon;use Illuminate\Support\Facades\{DB,Hash,Schema};use Illuminate\Validation\ValidationException;use Tests\TestCase;
final class NetworkSubscriptionFoundationTest extends TestCase
{
 protected function setUp():void{parent::setUp();if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')$this->markTestSkipped('Requires SQLite :memory:.');Carbon::setTestNow('2026-08-08 12:00:00');$this->schema();}
 protected function tearDown():void{Carbon::setTestNow();parent::tearDown();}
 public function test_subscription_relations_status_and_history_are_preserved():void{$tenant=$this->tenant('history');$plan=$this->plan('LOCAL300',300);$s=$this->createSubscription($tenant,$plan);$this->assertTrue($s->tenant->is($tenant));$this->assertTrue($s->plan->is($plan));app(SubscriptionService::class)->changeStatus($s,'ended');$next=$this->createSubscription($tenant,$plan);$this->assertCount(2,app(SubscriptionService::class)->historyForTenant($tenant));$this->assertTrue(app(SubscriptionService::class)->currentForTenant($tenant)->is($next));$this->assertDatabaseCount('network_subscription_events',3);}
 public function test_only_one_current_subscription_and_invalid_period_are_rejected():void{$tenant=$this->tenant('single');$plan=$this->plan('ONE',10);$this->createSubscription($tenant,$plan);$this->expectException(ValidationException::class);$this->createSubscription($tenant,$plan);}
 public function test_http_period_and_status_validation():void{$tenant=$this->tenant('validation');$plan=$this->plan('VALID',10);$this->actingAs($this->user('sysadmin@test.local','sysadmin'))->post("/network/tenants/{$tenant->id}/subscriptions",['plan_id'=>$plan->id,'status'=>'invalid','started_at'=>'2026-08-08 12:00:00','current_period_start'=>'2026-08-09','current_period_end'=>'2026-08-08'])->assertSessionHasErrors(['status','current_period_end']);}
 public function test_entitlement_snapshot_is_included_only_and_immutable_after_plan_change():void{$tenant=$this->tenant('snapshot');$plan=$this->plan('SNAP',300);$b2c=$this->module('B2C');$shipping=$this->module('SHIPPING');$plan->modules()->attach($b2c,['is_included'=>true,'limit_value'=>50]);$plan->modules()->attach($shipping,['is_included'=>false]);$s=$this->createSubscription($tenant,$plan);$this->assertSame(['B2C'],$s->entitlements()->pluck('code')->all());$plan->modules()->updateExistingPivot($b2c->id,['is_included'=>false,'limit_value'=>99]);$plan->modules()->updateExistingPivot($shipping->id,['is_included'=>true]);$this->assertSame(['B2C'],$s->entitlements()->pluck('code')->all());$this->assertSame(50,$s->entitlements()->first()->limit_value);$this->assertSame(300,$s->operations_limit);}
 public function test_entitlement_service_has_limit_and_database_prevents_duplicates():void{$tenant=$this->tenant('entitlements');$plan=$this->plan('ENT',null);$module=$this->module('API');$plan->modules()->attach($module,['is_included'=>true,'limit_value'=>25]);$s=$this->createSubscription($tenant,$plan);$service=app(EntitlementService::class);$this->assertTrue($service->has($tenant,'API'));$this->assertSame(25,$service->limit($tenant,'API'));$this->expectException(QueryException::class);Entitlement::create(['subscription_id'=>$s->id,'tenant_id'=>$tenant->id,'module_id'=>$module->id,'code'=>'API','is_enabled'=>true,'source'=>'plan']);}
 public function test_usage_record_aggregate_idempotency_and_current_period_only():void{$tenant=$this->tenant('usage');$plan=$this->plan('USE',300);$this->createSubscription($tenant,$plan);$usage=app(UsageService::class);$usage->record($tenant,'operations',37,'pilot-37');$usage->record($tenant,'operations',37,'pilot-37');$usage->record($tenant,'operations',5,'old',[],now()->subMonth());$summary=$usage->summary($tenant);$this->assertSame(37,$summary['used']);$this->assertSame(263,$summary['remaining']);$this->assertSame(12.33,$summary['percentage']);$this->assertFalse($summary['over_limit']);$this->assertDatabaseCount('network_usage_events',2);}
 public function test_usage_unlimited_and_over_limit():void{$unlimited=$this->tenant('unlimited');$this->createSubscription($unlimited,$this->plan('UNLIMITED',null));app(UsageService::class)->record($unlimited,'operations',7);$this->assertNull(app(UsageService::class)->summary($unlimited)['remaining']);$limited=$this->tenant('over');$this->createSubscription($limited,$this->plan('OVER',2));app(UsageService::class)->record($limited,'operations',3);$this->assertTrue(app(UsageService::class)->summary($limited)['over_limit']);$this->assertSame(0,app(UsageService::class)->remaining($limited));}
 public function test_tenant_usage_isolated_and_admin_reads_snapshot():void{[$a,$owner]=$this->tenantOwner('tenant-a');$b=$this->tenant('tenant-b');$plan=$this->plan('ISOLATED',100);$tracking=$this->module('TRACKING');$plan->modules()->attach($tracking,['is_included'=>true]);$this->createSubscription($a,$plan);$this->createSubscription($b,$plan);app(UsageService::class)->record($a,'operations',9);app(UsageService::class)->record($b,'operations',40);$this->actingAs($owner)->get($this->url($a,'/admin'))->assertOk()->assertSee('9')->assertSee('91')->assertDontSee('40 / 100');}
 public function test_suspended_subscription_limits_operation_but_network_remains_available():void{[$tenant,$owner]=$this->tenantOwner('suspended-sub');$plan=$this->plan('SUSP',20);$s=$this->createSubscription($tenant,$plan);app(SubscriptionService::class)->changeStatus($s,'suspended');$this->actingAs($owner)->get($this->url($tenant,'/admin'))->assertStatus(503)->assertSee('Servicio temporalmente no disponible');$this->post($this->url($tenant,'/admin/logout'))->assertRedirect('/admin/login');$this->get($this->url($tenant,'/admin/login'))->assertOk();$this->actingAs($this->user('network@test.local','sysadmin'))->get('/network')->assertOk();}
 public function test_network_manual_usage_tool_records_real_event():void{$tenant=$this->tenant('manual');$plan=$this->plan('MANUAL',300);$this->createSubscription($tenant,$plan);$this->actingAs($this->user('manual-network@test.local','sysadmin'))->post("/network/tenants/{$tenant->id}/usage",['metric'=>'operations','quantity'=>37,'idempotency_key'=>'manual:37'])->assertRedirect();$this->assertSame(37,app(UsageService::class)->total($tenant));$this->get('/network/dashboard')->assertOk()->assertSee('SUSCRIPCIONES')->assertSee('Activas');}
 private function createSubscription(Tenant$t,Plan$p,string$status='active'):Subscription{return app(SubscriptionService::class)->create($t,['plan_id'=>$p->id,'status'=>$status,'started_at'=>now()->startOfMonth(),'current_period_start'=>now()->startOfMonth(),'current_period_end'=>now()->endOfMonth(),'trial_ends_at'=>null,'grace_ends_at'=>null]);}
 private function tenantOwner(string$slug):array{$t=$this->tenant($slug);$t->domains()->create(['domain'=>$slug.'.zigo.local','type'=>'subdomain','environment'=>'production','is_primary'=>true,'status'=>'verified','verified_at'=>now()]);$u=$this->user($slug.'@test.local');$t->memberships()->create(['user_id'=>$u->id,'role'=>'owner','status'=>'active']);return[$t,$u];}
 private function url(Tenant$t,string$path):string{return'http://'.$t->primaryDomain()->first()->domain.$path;}private function tenant(string$slug):Tenant{return Tenant::create(['name'=>ucfirst($slug),'slug'=>$slug,'status'=>'active']);}private function plan(string$code,?int$limit):Plan{return Plan::create(['code'=>$code,'name'=>$code,'status'=>'active','currency'=>'MXN','included_operations'=>$limit]);}private function module(string$code):Module{return Module::create(['code'=>$code,'name'=>$code,'type'=>'addon','is_active'=>true,'sort_order'=>1]);}
 private function user(string$email,?string$role=null):User{$u=User::forceCreate(['name'=>'Test','email'=>$email,'password'=>Hash::make('tenant-secret'),'empresa_id'=>1]);if($role){$r=Roles::firstOrCreate(['slug'=>$role],['name'=>$role]);$u->roles()->attach($r->id);}return$u;}
 private function schema():void{foreach(['network_subscription_events','network_usage_events','network_entitlements','network_subscriptions','network_tenant_memberships','network_tenant_brandings','network_tenant_domains','network_plan_modules','network_tenants','network_plans','network_modules','users_roles','roles','users']as$t)Schema::dropIfExists($t);Schema::create('users',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->string('name');$t->string('email')->unique();$t->string('password');$t->unsignedBigInteger('empresa_id');$t->rememberToken();$t->timestamps();}));Schema::create('roles',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->string('name');$t->string('slug');$t->timestamps();}));Schema::create('users_roles',fn(Blueprint$t)=>tap($t,function($t){$t->unsignedBigInteger('user_id');$t->unsignedBigInteger('roles_id');}));Schema::create('network_modules',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->string('code')->unique();$t->string('name');$t->text('description')->nullable();$t->string('type');$t->boolean('is_active');$t->unsignedSmallInteger('sort_order');$t->timestamps();}));Schema::create('network_plans',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->string('code')->unique();$t->string('name');$t->text('description')->nullable();$t->string('status');$t->decimal('monthly_price',12,2)->nullable();$t->decimal('annual_price',12,2)->nullable();$t->char('currency',3);$t->unsignedInteger('included_operations')->nullable();$t->timestamps();}));Schema::create('network_tenants',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->uuid('uuid')->unique();$t->string('name');$t->string('slug')->unique();$t->string('status');$t->unsignedBigInteger('current_plan_id')->nullable();$t->timestamps();}));Schema::create('network_plan_modules',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('plan_id');$t->unsignedBigInteger('module_id');$t->boolean('is_included');$t->unsignedInteger('limit_value')->nullable();$t->timestamps();$t->unique(['plan_id','module_id']);}));Schema::create('network_tenant_domains',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('tenant_id');$t->string('domain')->unique();$t->string('type');$t->string('environment');$t->boolean('is_primary');$t->string('status');$t->timestamp('verified_at')->nullable();$t->timestamps();}));Schema::create('network_tenant_brandings',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('tenant_id')->unique();$t->string('brand_name')->nullable();$t->string('logo_path')->nullable();$t->string('primary_color',7)->nullable();$t->string('secondary_color',7)->nullable();$t->string('accent_color',7)->nullable();$t->string('favicon_path')->nullable();$t->string('support_email')->nullable();$t->string('support_phone')->nullable();$t->timestamps();}));Schema::create('network_tenant_memberships',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('user_id');$t->string('role');$t->string('status');$t->timestamps();$t->unique(['tenant_id','user_id']);}));Schema::create('network_subscriptions',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->uuid('uuid')->unique();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('plan_id');$t->string('status');$t->unsignedInteger('operations_limit')->nullable();foreach(['started_at','current_period_start','current_period_end','trial_ends_at','grace_ends_at','canceled_at','ended_at']as$c)$t->timestamp($c)->nullable();$t->timestamps();}));Schema::create('network_entitlements',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('module_id');$t->string('code');$t->boolean('is_enabled');$t->unsignedInteger('limit_value')->nullable();$t->string('source');$t->timestamps();$t->unique(['subscription_id','module_id']);$t->unique(['subscription_id','code']);}));Schema::create('network_usage_events',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->uuid('uuid')->unique();$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('subscription_id')->nullable();$t->string('metric');$t->unsignedInteger('quantity');$t->string('reference_type')->nullable();$t->string('reference_id')->nullable();$t->string('idempotency_key')->nullable();$t->timestamp('occurred_at');$t->json('metadata')->nullable();$t->timestamp('created_at')->nullable();$t->unique(['tenant_id','metric','idempotency_key']);}));Schema::create('network_subscription_events',fn(Blueprint$t)=>tap($t,function($t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('actor_user_id')->nullable();$t->string('event');$t->string('from_status')->nullable();$t->string('to_status')->nullable();$t->json('metadata')->nullable();$t->timestamp('created_at')->nullable();}));}
}
